/**
 * Refuse to go on while either tracked bundle disagrees with a fresh build.
 *
 * `client/client.js` and `lib/index.js` are generated by `build.mjs` and committed,
 * so the repository carries both the source and the artifact built from it - and the
 * two can drift apart in two different ways, which need two different checks:
 *
 *   1. **The artifact is not what the source would build.** This is the one that
 *      actually ships bugs, and the old check could not see it. It ran
 *      `git diff --exit-code -- <bundles>`, which asks whether the bundles differ
 *      from **git HEAD**. A source change that was never built leaves the bundles
 *      byte-identical to HEAD, so the comparison passed while the committed artifact
 *      still carried the old behaviour. Measured twice in this repository: once with
 *      `lib/index.js` and once with the code table embedded in it, both times
 *      reported as "matches the latest build".
 *
 *      So the question asked now is the one that was meant: **build, then compare the
 *      artifact with what the build produced.** A mismatch is a failure whatever the
 *      working tree looks like, whether the source was never built or the rebuilt
 *      bundle was never staged.
 *
 *   2. **The rebuilt bundle is not committed.** Even with check 1 passing, a bundle
 *      that a build regenerated but nobody staged would be published unchanged by the
 *      next `git archive` / `pnpm pack`, because packaging copies the working tree but
 *      a release is cut from a commit. `git diff --exit-code` catches that, so it is
 *      kept - as the *second* question rather than the only one.
 *
 * ## Building here, and why the earlier `pnpm build` is not reused
 *
 * `pnpm test` runs `build` before this script, so this build repeats work. That is
 * deliberate: the check has to be sound when run **on its own**, which is what
 * anybody debugging a stale bundle will do, and a check that only works in the one
 * order `pnpm test` happens to use is a check that silently passes everywhere else.
 * `build.mjs` takes about a second, and the alternative - trusting an artifact
 * produced by an earlier command with no way to know whether the source changed
 * since - is exactly the trust that failed twice.
 *
 * The build writes to `dist/` and `lib/` in place, so a stale `lib/index.js` is
 * replaced by the fresh one before the comparison. That is intentional: the artifact
 * is regenerated, the comparison is against the regeneration, and check 2 then says
 * whether the result was committed. It also means a run of this script **leaves a
 * correct bundle behind** rather than merely complaining about a wrong one.
 *
 * ## Outside a Git worktree
 *
 * A tarball unpacked from `pnpm pack` has no `.git`, and somebody checking that a
 * release artifact behaves should not be stopped by a check about commits. So the
 * Git-only half (check 2) is skipped there, with a sentence saying so - but the
 * build comparison still runs, because "this bundle is not what this source builds"
 * is a fact about the files in front of you and stays true without Git. That is the
 * one case where this script exits 0 with something skipped, and it says which half
 * it skipped rather than going quiet.
 *
 * `SKIP_TRACKED_BUNDLE_CHECK=1` skips everything and says so. It exists so a person
 * verifying an unpacked release, or bisecting a build problem, has a documented way
 * through rather than being forced to edit the script. A gate may distrust an agent;
 * it must not block the user.
 */
import { execFileSync } from "node:child_process"
import { readFileSync } from "node:fs"
import { fileURLToPath } from "node:url"

const ROOT = fileURLToPath(new URL("..", import.meta.url))
const BUNDLES = ["client/client.js", "lib/index.js"]

if (process.env.SKIP_TRACKED_BUNDLE_CHECK === "1") {
  console.log("tracked bundle check skipped: SKIP_TRACKED_BUNDLE_CHECK=1")
  process.exit(0)
}

/** Run a command in the repository root and return its stdout. */
const run = (command, args) => execFileSync(command, args, { cwd: ROOT, encoding: "utf8" })

/** Whether this directory is inside a Git work tree, which needs Git to answer. */
const inWorkTree = () => {
  try {
    run("git", ["rev-parse", "--is-inside-work-tree"])
    return true
  } catch {
    return false
  }
}

// Read the bundles before the build, so check 1 can say what changed rather than
// only that something did.
const before = new Map(BUNDLES.map((path) => [path, readFileSync(`${ROOT}${path}`, "utf8")]))

console.log("building to compare the committed bundles against a fresh build")
execFileSync("node", ["build.mjs"], { cwd: ROOT, stdio: "inherit" })

const stale = BUNDLES.filter((path) => readFileSync(`${ROOT}${path}`, "utf8") !== before.get(path))
if (stale.length > 0) {
  // The advice is deliberately "look first, then stage", not a bare `git add`. The
  // check rebuilt the artifact on its way to this message, so following it blindly
  // stages a bundle that is now correct against a source change nobody has looked at -
  // and the likeliest reason to be here is a source edit that was never built, whose
  // author is the only one who knows whether it is finished and what else it needs.
  console.error(
    `generated bundles are stale: ${stale.join(", ")}\n`
    + "  The committed artifact is not what this source builds, so the plugin that ships\n"
    + "  would not be the plugin in this commit. A fresh build has replaced the artifact in\n"
    + "  the working tree, so the file on disk is now correct - but whether the change that\n"
    + "  made it stale is ready to commit is not this check's to decide.\n"
    + "  Look at `git status` before staging: if you edited anything under src/ or build.mjs,\n"
    + "  confirm those are in the same commit, then stage what belongs together:\n"
    + `  git add ${stale.join(" ")}`,
  )
  process.exit(1)
}

if (!inWorkTree()) {
  console.log("tracked bundles match this source (no Git work tree here, so the committed-state half was skipped)")
  process.exit(0)
}

try {
  run("git", ["diff", "--exit-code", "--", ...BUNDLES])
} catch {
  // Here the working copy is already correct and the build did not have to change it,
  // so a bare `git add` is the whole of the remedy - a release cut from the commit
  // would otherwise ship the older artifact. Still worth naming what is being staged,
  // since an unrelated edit to one of these files would be swept in with it.
  console.error(
    "generated bundles are rebuilt but not committed\n"
    + "  The working copy is correct and the commit is not, so a release cut from the\n"
    + "  commit would ship the older artifact. Stage what the build produced - and check\n"
    + "  `git status` first, so nothing else rides along in the same `git add`:\n"
    + `  git add ${BUNDLES.join(" ")}`,
  )
  process.exit(1)
}

console.log("tracked client and host bundles are what this source builds, and are committed")
